-- Catalog metadata is not a chat. Rooms remain lazy: only a real join creates one.
create schema course_private;
revoke all on schema course_private from public,anon,authenticated;
grant usage on schema course_private to service_role;
create table course_private.catalog (
 code text primary key check(code ~ '^[A-Z]{2,5} [0-9]{3,4}[A-Z]?$'),
 title text not null,
 levels jsonb not null,
 source_url text not null check(source_url like 'https://catalog.tamu.edu/%'),
 edition text not null,
 fetched_at timestamptz not null
);
alter table course_private.catalog enable row level security;
create policy "Server reads official catalog" on course_private.catalog for select to service_role using(true);
revoke all on course_private.catalog from public,anon,authenticated;
grant select on course_private.catalog to service_role;


