ce_url=excluded.source_url,edition=excluded.edition,fetched_at=excluded.fetched_at;

create function course_private.canonical_course() returns trigger language plpgsql security invoker set search_path='' as $$
declare item course_private.catalog; semester text;
begin
 if new.kind<>'course' then return new;end if;
 select *into item from course_private.catalog where code=new.meta->>'code';
 if item.code is null then raise exception 'invalid:Choose a course from the official A&M catalog.';end if;
 semester:=new.meta->>'term';
 if semester is null or semester !~ '^(Spring|Summer|Fall) 20[0-9]{2}$' then raise exception 'invalid:Choose a semester.';end if;
 if right(semester,4)::int not between extract(year from now())::int-1 and extract(year from now())::int+1 then raise exception 'invalid:Choose a current or upcoming semester.';end if;
 new.id:=item.code||'-'||semester;new.title:=item.code;
 new.meta:=jsonb_build_object('code',item.code,'title',coalesce(nullif(item.title,''),item.code),'term',semester,'icon','book.closed.fill');
 return new;
end $$;
create trigger canonical_official_course before insert on social_private.rooms for each row execute function course_private.canonical_course();

create function course_private.membership_limit() returns trigger language plpgsql security invoker set search_path='' as $$
declare semester text;
begin
 if new.status<>'accepted' then return new;end if;
 select meta->>'term' into semester from social_private.rooms where id=new.room and kind='course';
 if semester is null then return new;end if;
 if exists(select 1 from social_private.room_members where room=new.room and member=new.member and status='accepted') then return new;end if;
 if (select count(*)from social_private.room_members m join social_private.rooms r on r.id=m.room where m.member=new.member and m.status='accepted'and r.kind='course'and r.meta->>'term'=semester)>=20 then raise exception 'full:Join up to 20 classes per semester.';end if;
 return new;
end $$;
create trigger official_course_membership_limit before insert or update of status on social_private.room_members for each row execute function course_private.membership_limit();

create function public.course_activity(p_hash text,p_term text)returns jsonb language plpgsql security invoker set search_path='' as $$
declare me uuid;
begin
 me:=social_private.require_member(p_hash);
 if p_term !~ '^(Spring|Summer|Fall) 20[0-9]{2}$' then raise exception 'invalid:Choose a semester.';end if;
 return jsonb_build_object('courses',coalesce((select jsonb_agg(jsonb_build_object('code',code,'members',members)order by members desc,code)from(
  select r.meta->>'code' code,count(*)members
  from social_private.rooms r join social_private.room_members rm on rm.room=r.id join social_private.members m on m.id=rm.member
  where r.kind='course'and r.status='active'and r.meta->>'term'=p_term and rm.status='accepted'and not m.banned
  group by r.meta->>'code'
 )active),'[]'));
exception when raise_exception then return jsonb_build_object('error',split_part(sqlerrm,':',2),'code',split_part(sqlerrm,':',1));
end $$;
revoke all on all functions in schema course_private from public,anon,authenticated;
grant execute on all functions in schema course_private to service_role;
revoke all on function public.course_activity(text,text)from public,anon,authenticated;
grant execute on function public.course_activity(text,text)to service_role;

-- Professional course numbers may have four digits. Keep the existing gateway
-- and all its privacy checks, widening only its course-code grammar.
do $$declare definition text;old_pattern text:='^[A-Z]{2,5} [0-9]{3}[A-Z]?$';begin
 definition:=pg_get_functiondef('public.social_gateway(text,text,jsonb)'::regprocedure);
 if strpos(definition,old_pattern)=0 then raise exception 'Expected course validation was not found';end if;
 execute replace(definition,old_pattern,'^[A-Z]{2,5} [0-9]{3,4}[A-Z]?$');
end $$;

create index rooms_active_course_term on social_private.rooms ((meta->>'term')) where kind='course' and status='active';
